        "compatibilities",
        "status",
        "requiresAttributes",
        "registeredAt",
        "registeredBy",
    }
    return {key: task_definition[key] for key in accepted_keys}


def set_readonly_root_filesystem(task_definition: dict):
    container_definitions = task_definition["containerDefinitions"]
