def handler(event: Event, _) -> HandlerResponse:
    try:
        ec2_client = connect_to_service("ec2")
        group_id = event.get("GroupId")

        ip_permissions = get_permissions(group_id)
        ingress_permissions = ip_permissions.get("IngressPermissions")
