                }

        return {
            "Message": "Bucket public access block configuration successfully set.",
            "Valid": True,
            "PublicAccessConfig": configuration,
        }
    except Exception as e:
        raise RuntimeError(
            f"Encountered error validating s3 bucket {bucket_name} public access block: {str(e)}"
        )

